class Solution:
    def updateMatrix(self, mat: list[list[int]]) -> list[list[int]]:
        m, n = len(mat), len(mat[0])
        DIR = [0,1,0,-1,0]
        queue = deque()
        for i in range(m):
            for j in range(n):
                if mat[i][j] == 0:
                    queue.append((i, j))
        seen = set()
        while queue:
            k = len(queue)
            for _ in range(k):
                r, c = queue.popleft()
                for i in range(4):
                    nr, nc = r + DIR[i], c + DIR[i + 1]
                    if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in seen and mat[nr][nc] != 0:
                        queue.append((nr,nc))
                        mat[nr][nc] = mat[r][c] + 1
                        seen.add((nr,nc))
        return mat
